import { describe, it, expect } from 'vitest';
import { handleRefund } from '../refunds';

describe('ENG-412', () => {
  it('ignores a replayed webhook', async () => {
    const evt = { id: 'evt_1', amount: 500 };
    await handleRefund(evt);
    expect(await handleRefund(evt)).toEqual({ status: 'duplicate' });
  });
});
